M('drybasis',P('濕基 Cw=40 mg/m³；水蒸氣體積分率 H=0.10','Wet concentration Cw=40 mg/m³; water-vapour volume fraction H=0.10'),'Cd=Cw/(1-H)','40/(1-0.10)','mg per dry m³',P('只將 H 改成 0.20','Change only H to 0.20'),'40/(1-0.20)',P('移除水蒸氣後同量污染物對應較小乾氣體積，因此乾基濃度高於濕基。','Removing water vapour leaves the same pollutant in a smaller dry-gas volume, so dry concentration exceeds wet concentration.'),P('理想氣體且前後溫壓基準一致，未考慮污染物溶入冷凝水。','Ideal gas with matching temperature and pressure bases, excluding pollutant dissolution in condensate.'),P('保留含濕量與氣體基準，檢查取樣調理是否同時移除可溶性污染物。','Retain moisture and gas bases and check whether sample conditioning also removes soluble pollutants.'),P('把已乾燥的訊號再作乾基校正會重複放大濃度。','Applying dry correction again to an already dry measurement double-increases concentration.'),P('乾基與濕基只差標籤，數值必定相同。','Dry and wet bases differ only in label and always have equal values.'))
M('network_density',P('都市面積 A=36 km²；感測站 N=16','Urban area A=36 km²; number of sensors N=16'),'s=sqrt(A/N)','math.sqrt(36/16)','km nominal spacing',P('只將 N 改成 36','Change only sensor count to 36'),'math.sqrt(36/36)',P('平均面積平方根給名目站距，不能代表街谷或污染源周邊的實際解析度。','Square root of mean area per station gives nominal spacing, not actual resolution near street canyons or sources.'),P('均勻平面方格的幾何近似，不是採樣密度或法定設站建議。','A geometric approximation to a uniform square grid, not a station-density or regulatory siting recommendation.'),P('將站點疊在道路、地形與使用目的圖，檢查空間缺口及重複代表區。','Overlay stations on roads, terrain and measurement objectives and check gaps and redundant representation.'),P('站點集中於供電方便處會留下系統性盲區。','Clustering stations where power is convenient creates systematic blind spots.'),P('站點數量相同就保證兩座城市擁有相同空間代表性。','Equal sensor counts guarantee equal spatial representativeness in two cities.'))
M('humidity_bias',P('假想粒子訊號 y=C*(1+a*RH)；真值 C=20 µg/m³；a=0.5；RH=0.60（分率）','Hypothetical particle signal y=C*(1+a*RH); true C=20 µg/m³; a=0.5; RH=0.60 as a fraction'),'bias=C*a*RH','20*0.5*0.60','µg/m³',P('只將 RH 改成 0.90','Change only RH to 0.90'),'20*0.5*0.90',P('光學粒子訊號可能受吸濕增長及粒徑組成影響；本線性式只示範環境依賴偏差。','Optical particle signals may respond to hygroscopic growth and size distribution; this linear equation only illustrates environment-dependent bias.'),P('原創虛構響應係數，非任何品牌校正式，不能將此式用於實際資料修正。','An invented response coefficient, not a calibration for any brand and not for correcting real observations.'),P('共置時同步量濕度，依濕度分組畫殘差，並用未訓練季節資料驗證。','Measure humidity during colocation, inspect humidity-stratified residuals and validate with an unseen season.'),P('只在乾燥期建立校正可能在潮濕期系統性偏高。','Dry-period-only calibration can develop systematic positive bias during humid conditions.'),P('一次共置校正可永久消除所有季節與氣膠成分效應。','One colocation permanently removes all seasonal and aerosol-composition effects.'))
M('spreading',P('自由場點音源參考距離 r1=10 m；接收距離 r2=20 m','Free-field point-source reference distance r1=10 m; receiver distance r2=20 m'),'deltaL=20*log10(r2/r1)','20*math.log10(20/10)','dB reduction',P('只將 r2 改成 30 m','Change only r2 to 30 m'),'20*math.log10(30/10)',P('球面擴散令強度按距離平方降低；線聲源、公路與反射環境不能直接套相同衰減。','Spherical spreading reduces intensity with distance squared; line sources, highways and reflective environments need different treatment.'),P('無反射、無屏障、遠場點源；僅為與屏障作用比較的基線。','Unobstructed reflection-free far-field point source; a baseline for comparison with barriers only.'),P('確認聲源幾何與背景聲，沿多距離點量測並檢查是否符合點源假設。','Check source geometry and background and measure at multiple distances to test point-source assumptions.'),P('把長道路當孤立點音源會高估距離衰減。','Treating a long road as one point source overstates distance attenuation.'),P('任何道路噪音只要距離加倍就一定降低同一固定分貝值。','Every road-noise case loses the same fixed decibel amount when distance doubles.'))
M('gap_transmission',P('總面積 A=100 m²；開口 Ag=1 m²；板材能量穿透率 τp=0.001；開口 τg=1','Total area A=100 m²; opening Ag=1 m²; panel energy transmission τp=0.001; opening τg=1'),'TL=-10*log10(((A-Ag)*tau_p+Ag*tau_g)/A)','-10*math.log10(((100-1)*0.001+1)/100)','dB composite transmission loss',P('只將 Ag 改成 2 m²','Change only opening area to 2 m²'),'-10*math.log10(((100-2)*0.001+2)/100)',P('平行穿透路徑的能量按面積加權，少量無阻隔開口即可主導穿透。','Energy through parallel transmission paths is area weighted; small unblocked openings can dominate transmission.'),P('均勻入射的理想面積平均，不含繞射與反射；此穿透損失不同於現地插入損失。','Ideal area averaging under uniform incidence, excluding diffraction and reflection; transmission loss differs from field insertion loss.'),P('檢查門縫、排水孔與板間接縫，將透射與繞射分開建模。','Inspect door gaps, drains and joints and model transmission separately from diffraction.'),P('只採用板材實驗室數據會忽略現地開口造成的漏聲。','Panel laboratory data alone overlooks field openings and leakage.'),P('使用高隔音板材就能忽略所有接縫和開口。','High-transmission-loss panels make every joint and opening irrelevant.'))
M('transport_lca',P('運輸質量 m=1 t；距離 d=80 km；假想係數 f=0.08 kg CO₂e/(t·km)','Transport mass m=1 t; distance d=80 km; hypothetical factor f=0.08 kg CO₂e/(t·km)'),'I=m*d*f','1*80*0.08','kg CO₂e',P('只將 d 改成 140 km','Change only distance to 140 km'),'1*140*0.08',P('噸公里乘係數建立運輸清單，載重、空車回程與運具須在係數或活動量中一致處理。','Tonne-kilometres multiplied by a factor create transport inventory; payload, empty return and mode must be handled consistently.'),P('係數完全是假設，不對應實際車隊；未另計入已包含於係數的活動以免重複。','The factor is hypothetical and represents no actual fleet; do not separately count activities already included in it.'),P('記錄重量、路程、運具與回程邊界，檢查 t、kg、km 的換算。','Record mass, distance, mode and return-trip boundary and verify t, kg and km conversions.'),P('把一噸投入與一噸合格產出視為同一功能單位會忽略損失。','Equating one tonne input with one tonne qualified output ignores losses.'),P('運輸距離較短就保證整個回收生命週期影響較低。','A shorter haul guarantees lower impact across the entire recycling lifecycle.'))
M('functional_output',P('每噸投入耗電 E=120 kWh；合格產出率 y=0.75 t/t','Electricity per input tonne E=120 kWh; qualified yield y=0.75 t/t'),'Eproduct=E/y','120/0.75','kWh/t qualified output',P('只將 y 改成 0.60 t/t','Change only qualified yield to 0.60 t/t'),'120/0.60',P('功能單位決定分母；按投入計算與按合格產品計算會因損失率而不同。','The functional unit sets the denominator; input-based and qualified-product-based values differ with losses.'),P('單一產品且固定投入能耗，未分配其他副產品；不是產品效能完全等價的證明。','One product and fixed input energy, without coproduct allocation; this does not prove equivalent product performance.'),P('量合格品、次品與殘渣，明確寫出比較是廢棄物處理服務還是材料供應服務。','Measure qualified output, rejects and residues and specify whether comparison concerns waste-treatment or material-supply service.'),P('比較不同分母的數值會使低產率程序看似省能。','Comparing different denominators can make a low-yield process appear efficient.'),P('每噸進料與每噸合格再生料的指標一定相同。','Per-tonne-input and per-tonne-qualified-recycled-product indicators are always identical.'))

C('b496',P('把取樣、校正、氣體基準與品質旗標串成可信的連續排放資料','Link sampling, calibration, gas bases and quality flags into credible continuous emission data'),'environment-monitoring',['cems','cemsps','control'],[
U(P('量測目的與取樣代表性','Measurement objective and sample representativeness'),P('先定污染物、時間窗和煙道截面；單一分析儀讀數需有代表性取樣與適用性能規格支撐。','Define pollutant, time interval and stack cross-section; an analyzer reading needs representative sampling and applicable performance specifications.'),'coverage'),
U(P('取樣管與全系統延遲','Sampling line and whole-system lag'),P('把探頭、加熱管、調理器和分析儀畫成流程，分清資料時間與樣本離開煙道的時間。','Map probe, heated line, conditioner and analyzer and distinguish recorded time from the time the sample left the stack.'),'lag'),
U(P('水分與乾濕基換算','Moisture and wet/dry conversion'),P('保留樣本含濕與調理方式，檢查可溶性物種是否在冷凝過程流失。','Retain moisture and conditioning method and check whether soluble species are lost during condensation.'),'drybasis'),
U(P('零點、跨度與線性','Zero, span and linearity'),P('用多點參考資料分離偏移與增益誤差，將定期查核與實際調整分開記錄。','Separate offset and gain errors using multipoint references and distinguish periodic checks from adjustments.'),'calibration'),
U(P('參考氧濃度校正','Reference-oxygen correction'),P('對需要的報告項才套用適用參考氧值，保留原始乾基濃度並防止重複校正。','Apply an applicable reference oxygen only to report items requiring it, retain raw dry concentration and prevent duplicate correction.'),'oxygen_correction'),
U(P('濃度轉質量排放','Concentration to mass emission'),P('把流量與濃度的乾濕、溫壓及時間基準對齊，再算質量率；單獨濃度無法描述總負荷。','Align moisture, temperature, pressure and time bases of flow and concentration before calculating mass rate.'),'gas_mass'),
U(P('與獨立參考法比較','Comparison with an independent reference'),P('使用未參與校正的參考資料查核殘差，檢查全系統誤差而非只驗分析儀。','Check residuals with independent reference data excluded from calibration and assess the full system rather than the analyzer alone.'),'calibration'),
U(P('負荷不確定度預算','Load uncertainty budget'),P('濃度與流量共用溫壓訊號時可能相關，先檢查共變異才使用獨立誤差近似。','Concentration and flow may share temperature or pressure signals; inspect covariance before using an independent-error approximation.'),'uncertainty'),
U(P('有效資料與缺測旗標','Valid data and missing-value flags'),P('將校正、維護、異常及通訊斷線分開標記，缺值絕不能直接當作零排放。','Flag calibration, maintenance, faults and communication loss separately and never treat missing values as zero emissions.'),'coverage'),
U(P('事件回放與報告追溯','Event replay and report traceability'),P('讓玩家由報告值回查原始訊號、校正版本和品質旗標，用可用率交代系統維護而非取代合格資料率。','Trace reports back to raw signals, calibration versions and quality flags; use availability for maintenance performance, not valid-data compliance.'),'availability')])

C('b497',P('以共置驗證、空間代表性與資料品質建立都市空氣感測網','Build an urban air-sensor network through colocation, spatial representativeness and data quality'),'environment-monitoring',['sensor','sensorbox','cems'],[
U(P('設站問題與空間尺度','Siting question and spatial scale'),P('先選交通、背景或社區比較目的，再配置站點；名目站距不能代表街谷中的污染梯度。','Choose traffic, background or community-comparison objectives before siting; nominal spacing does not resolve street-canyon gradients.'),'network_density'),
U(P('共置與時間對齊','Colocation and time alignment'),P('將感測器與參考儀放在可比較的位置和時段，保留時鐘、平均窗與進氣高度差異。','Colocate sensors and references comparably and retain differences in clock, averaging interval and inlet height.'),'bias'),
U(P('響應曲線與校正集','Response curve and calibration dataset'),P('校正資料要涵蓋預期濃度範圍，分開訓練、驗證與外部測試，避免把擬合成績當泛化能力。','Cover the expected concentration range and separate training, validation and external testing rather than equating fit with generalization.'),'calibration'),
U(P('濕度交互作用','Humidity interaction'),P('追蹤光學粒子感測的濕度依賴；此虛構線性式只練習識別偏差，不能當成可下載的現場校正式。','Track humidity dependence in optical particle sensing; the invented linear equation teaches bias identification rather than supplying a field correction.'),'humidity_bias'),
U(P('平均偏差與誤差抵銷','Mean bias and error cancellation'),P('把高低濃度時的誤差分開畫圖；整體平均誤差接近零可能掩蓋兩端相反偏差。','Plot errors separately at low and high concentrations because near-zero overall bias can conceal opposite endpoint errors.'),'bias'),
U(P('RMSE 與保留資料驗證','RMSE and held-out validation'),P('以未參與擬合的配對資料計算誤差，並同時報斜率、偏差和季節覆蓋。','Calculate error on held-out paired data and also report slope, bias and seasonal coverage.'),'rmse'),
U(P('缺值、離線與異常旗標','Gaps, offline periods and outlier flags'),P('將斷電、網路、校正和真實污染尖峰分開，不能為了漂亮曲線刪除所有極端值。','Separate power loss, networking, calibration and true pollution peaks; do not delete all extremes to create a smooth curve.'),'coverage'),
U(P('地圖插值與代表範圍','Mapping interpolation and representation'),P('圖上標出站位、空白區與不確定範圍，避免把平滑插值視為每條街的實測值。','Show sites, unsampled areas and uncertainty on maps rather than presenting smooth interpolation as direct measurement on every street.'),'network_density'),
U(P('漂移與定期再共置','Drift and repeat colocation'),P('比較感測器老化前後的保留測試資料；維修或更換之後保留版本資訊以避免拼接偏差。','Compare held-out tests before and after ageing and retain versions after maintenance or replacement to avoid splicing bias.'),'rmse'),
U(P('用途限制與公眾解讀','Fitness for purpose and public interpretation'),P('發布數值同時提供時間窗、有效率和校正版本，說明此網路的研究用途，不能自動等同法定監測站。','Publish averaging intervals, completeness and calibration version with readings, explaining research purpose without equating the network automatically with regulatory stations.'),'coverage')])

C('b498',P('從聲能、頻率與繞射幾何到屏障插入損失驗證','Connect acoustic energy, frequency and diffraction geometry with verified barrier insertion loss'),'environment-monitoring',['noise','noisepack'],[
U(P('聲源盤查與分貝加總','Source inventory and decibel addition'),P('在道路與設備場景分離多個不相關音源，先轉線性能量再加總，保留頻帶與加權方式。','Separate uncorrelated road and equipment sources, add linear energies and preserve frequency bands and weighting.'),'logsum'),
U(P('基線聲級與時間尺度','Baseline level and time scale'),P('把交通尖峰和離峰按實際時長合併，不使用聲級數值的算術平均。','Combine peak and off-peak traffic using actual durations rather than arithmetic averaging of decibel levels.'),'energyavg'),
U(P('距離衰減與聲源幾何','Distance loss and source geometry'),P('用孤立設備的點源例建立概念，接著指出長道路是延伸聲源，不能直接沿用點源尺度。','Develop intuition with an isolated point-source machine, then identify a long road as an extended source requiring different scaling.'),'spreading'),
U(P('頻帶與波長','Frequency bands and wavelength'),P('同一屏障對不同頻率的效果不同，先用波長與屏障高度、縫隙尺寸比較。','Compare wavelength with barrier height and gap dimensions because performance varies across frequency.'),'wavelength'),
U(P('頂部繞射與路徑差','Top-edge diffraction and path difference'),P('拖曳教學聲源、屏障和接收點，量兩段繞射路徑；路徑差只是衰減模型的輸入。','Drag the teaching source, barrier and receiver and measure both diffracted segments; path difference is an attenuation-model input only.'),'pathdiff'),
U(P('端部與有限長度效應','Ends and finite-length effects'),P('把接收點移向屏障端部，另畫側向繞射路徑，不能只檢查中央剖面。','Move the receiver toward an end and draw the lateral diffraction path instead of checking only the central section.'),'pathdiff'),
U(P('板材穿透與開口漏聲','Panel transmission and opening leakage'),P('在理想板面加入接縫與開口，觀察能量穿透率的面積加權；同時保留繞射造成的另一條路。','Add joints and openings to an ideal panel and examine area-weighted transmission while retaining diffraction as a separate path.'),'gap_transmission'),
U(P('現地插入損失','Field insertion loss'),P('屏障前後都用同一接收點並用參考麥克風校正聲源差異，將天氣變化列入紀錄。','Use the same receiver before and after, a reference microphone for source changes and a weather record.'),'insertion'),
U(P('背景聲與效果上限','Background sound and performance floor'),P('當目標聲源降低後，未被屏障遮住的背景聲可能主導總聲級，不能期待總值無限制下降。','As the target source falls, unshielded background may dominate the total and limit observed improvement.'),'logsum'),
U(P('整體方案與驗證交接','Integrated proposal and verification handoff'),P('交付頻帶結果、量測幾何與前後對照，另列排水、視距、結構及維修需求由對應專業驗證。','Handoff frequency-band results, surveyed geometry and matched comparisons, while routing drainage, visibility, structure and maintenance to the appropriate professional checks.'),'insertion')])

C('b499',P('把污水臭氣收集、傳質、生物反應與床層維護串成完整流程','Connect wastewater odour collection, mass transfer, biodegradation and bed maintenance'),'environment-waste',['odor','compost','control'],[
U(P('臭味源與收集邊界','Odour sources and collection boundary'),P('在進水、污泥儲存與脫水區分別標記臭氣源，先確認是否有效收集再討論末端處理率。','Mark odour sources at inlet works, sludge storage and dewatering and establish capture before interpreting downstream removal.'),'gas_mass'),
U(P('集氣管與抽風需求','Collection ducts and blower demand'),P('分開罩口、管路與床層壓降，風量過少可能漏收，過大則增加負荷與耗能。','Separate hood, duct and bed pressure losses; low flow may lose capture while excessive flow adds load and energy.'),'blower'),
U(P('入口濃度與污染負荷','Inlet concentration and contaminant loading'),P('依物種配對氣量與濃度，臭味感受不能直接由單一化合物的質量濃度完整描述。','Pair species-specific concentration with flow; one compound mass concentration cannot fully describe perceived odour.'),'gas_mass'),
U(P('空床停留時間','Empty-bed residence time'),P('先以總床體積計算 EBRT，再檢查氣體是否均勻穿床；它不等於每個分子的實際孔隙時間。','Calculate EBRT from total bed volume, then check flow distribution; it does not equal every molecule’s actual pore residence.'),'ebrt'),
U(P('生物膜傳質與反應','Biofilm mass transfer and reaction'),P('污染物先由氣相移入濕潤生物膜再被利用，教學衰減常數整合多重作用，不能直接視為單一菌種速率。','Contaminants transfer from gas into moist biofilm before utilization; a teaching decay constant combines effects and is not a species-specific rate.'),'decay'),
U(P('水分與床材條件','Moisture and packing condition'),P('床材太乾會限制生物作用，太濕可能堵塞孔隙；用濕乾質量記帳，不由單一平均值決定全床狀態。','Dry packing can limit biology while wet packing can obstruct pores; track wet and dry mass rather than inferring the whole bed from one mean.'),'dry_solids'),
U(P('消除容量與去除百分比','Elimination capacity and percent removal'),P('同時比較每床體積移除量與去除比例，判讀低濃度高去除率是否具有足夠負荷能力。','Compare removal per bed volume with percentage removal to assess whether high removal at low concentration demonstrates sufficient capacity.'),'elimination'),
U(P('壓降、壓實與氣流旁通','Pressure drop, compaction and bypass'),P('將床層壓降和分區流量一起看；壓降降低可能代表旁通，也可能代表清理改善，須有其他證據。','Interpret bed pressure with zonal flow; lower pressure may indicate bypass or improved cleaning and needs corroboration.'),'pressure'),
U(P('變動負荷與重新評估','Variable loading and reassessment'),P('用暴雨進水或污泥作業的假想尖峰改變負荷，檢查排放質量、床體反應與嗅覺評估是否一致。','Apply hypothetical peaks from storm inflow or sludge work and check consistency among emitted mass, bed response and odour assessment.'),'elimination'),
U(P('維護紀錄與長期表現','Maintenance records and long-term performance'),P('把床材更換、加濕故障、風機停機與周界氣味事件對時，設備可用不等於持續達到處理目的。','Align packing replacement, moisture faults, blower outages and boundary odour events; equipment availability does not establish continuous treatment performance.'),'availability')])

C('b500',P('用功能單位、物料收支與替代情境比較資源回收生命週期','Compare recycling lifecycles through functional units, material balances and substitution scenarios'),'environment-waste',['warm','warmdocs','wi'],[
U(P('決策目的與功能單位','Decision purpose and functional unit'),P('先決定比較一噸廢棄物處理服務，還是一噸符合品質的再生材料，兩者分母不同不能混用。','First choose between one tonne of waste-treatment service and one tonne of qualified recycled material; their denominators cannot be mixed.'),'functional_output'),
U(P('邊界、清單與回收率','Boundary, inventory and recovery yield'),P('畫出收運、分類、再加工和殘渣出口，保存進料成分與回收率，避免把所有進料都視為再生品。','Map collection, sorting, reprocessing and residue outlets and retain composition and recovery yield instead of treating all input as product.'),'recovery'),
U(P('合格產出與品質差異','Qualified output and quality differences'),P('低純度再生料可能不能一比一替代原生料，合格率與材料功能需獨立驗證。','Low-purity recycled material may not displace virgin material one-for-one; qualified yield and material function need separate verification.'),'functional_output'),
U(P('廠內電力與地域係數','Plant electricity and regional factors'),P('將用電量與係數年份、地域和方法配對，所有教學係數明示是假想。','Match electricity with factor year, region and accounting method and explicitly label all teaching factors hypothetical.'),'lca_energy'),
U(P('運輸噸公里與回程','Transport tonne-kilometres and return trips'),P('追蹤原料、再生品和殘渣的運輸路徑，將空車回程放在一致邊界中避免遺漏或重算。','Track transport of inputs, products and residues and handle empty returns consistently to avoid omission or duplication.'),'transport_lca'),
U(P('多產品共同負荷分配','Shared-burden allocation among products'),P('一條線產出多種材料時，公開選擇質量或其他分配法的理由，並檢查分配後總量守恆。','For multiple outputs, disclose the rationale for mass or another allocation and check total-burden conservation.'),'allocation'),
U(P('替代生產與避免負荷','Displaced production and avoided burden'),P('把實際處理負荷與假設替代信用分欄，再比較基準情境；負淨值不代表廠房沒有排放。','Separate physical treatment burdens from assumed displacement credits before baseline comparison; negative net impact does not mean a plant emits nothing.'),'lca_net'),
U(P('殘渣、損失與邊界閉合','Residues, losses and boundary closure'),P('補入不可回收殘渣的處理與損失，透過質量收支檢查有沒有只計好產品而忽略廢棄出口。','Include treatment of unrecoverable residues and losses and use mass balance to detect product-only accounting that omits waste outlets.'),'fraction'),
U(P('情境敏感度與排序反轉','Scenario sensitivity and ranking reversal'),P('改變替代率、品質和電力條件，辨識哪一個假設會使方案排序改變，而非只報單一最佳數字。','Vary displacement, quality and electricity conditions to identify assumptions that reverse rankings rather than reporting one favourable number.'),'lca_net'),
U(P('資料品質與比較結論','Data quality and comparative interpretation'),P('把資料版本、邊界、方法及未涵蓋影響交給下一位玩家；本課算例只示範碳清單，不能代表所有環境影響。','Handoff data versions, boundaries, methods and omitted impacts; these carbon-inventory examples do not represent every environmental impact category.'),'lca_energy')])
